/* Bounded native capsule decoder. No libc/TLS/heap/I/O. Unsupported or
 * oversized JSON is a known rejection, never a fabricated cleanup success. */
#include "receipt-json.h"
static void rj_ws(Rj*p){while(p->at<p->bytes&&(p->text[p->at]==32||p->text[p->at]==9||p->text[p->at]==10||p->text[p->at]==13))p->at++;}
static uint16_t rj_new(Rj*p,unsigned kind,size_t start){if(p->count==512)return RJ_NONE;uint16_t n=p->count++;p->nodes[n]=(RjNode){.start=(uint32_t)start,.child=RJ_NONE,.next=RJ_NONE,.kind=(uint8_t)kind};return n;}
static int rj_equal(const Rj*p,uint16_t a,uint16_t b){const RjNode*x=&p->nodes[a],*y=&p->nodes[b];if(x->end-x->start!=y->end-y->start)return 0;for(uint32_t i=0;i<x->end-x->start;i++)if(p->text[x->start+i]!=p->text[y->start+i])return 0;return 1;}
static uint16_t rj_string(Rj*p){size_t begin=p->at++;uint16_t n=rj_new(p,RJ_STRING,begin+1);if(n==RJ_NONE)return n;while(p->at<p->bytes){unsigned c=p->text[p->at++];if(c=='"'){p->nodes[n].end=(uint32_t)p->at-1;return n;}if(c<32)return RJ_NONE;if(c=='\\'){if(p->at==p->bytes)return RJ_NONE;c=p->text[p->at++];if(c=='u'){for(unsigned j=0;j<4;j++){if(p->at==p->bytes)return RJ_NONE;c=p->text[p->at++];if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F')))return RJ_NONE;}}else if(c!='"'&&c!='\\'&&c!='/'&&c!='b'&&c!='f'&&c!='n'&&c!='r'&&c!='t')return RJ_NONE;}}return RJ_NONE;}
static uint16_t rj_value(Rj*p,unsigned depth){rj_ws(p);if(depth>16||p->at==p->bytes)return RJ_NONE;unsigned c=p->text[p->at];if(c=='"')return rj_string(p);size_t begin=p->at;uint16_t n;
 if(c=='{'||c=='['){p->at++;n=rj_new(p,c=='{'?RJ_OBJECT:RJ_ARRAY,begin);if(n==RJ_NONE)return n;uint16_t last=RJ_NONE;rj_ws(p);if(p->at<p->bytes&&p->text[p->at]==(c=='{'?'}':']')){p->at++;p->nodes[n].end=(uint32_t)p->at;return n;}
  for(;;){uint16_t key=RJ_NONE,v;rj_ws(p);if(c=='{'){if(p->at==p->bytes||p->text[p->at]!='"')return RJ_NONE;key=rj_string(p);if(key==RJ_NONE)return key;for(uint32_t z=p->nodes[key].start;z<p->nodes[key].end;z++)if(p->text[z]=='\\'||p->text[z]>=128)return RJ_NONE;for(uint16_t k=p->nodes[n].child;k!=RJ_NONE;){if(rj_equal(p,k,key))return RJ_NONE;uint16_t value=p->nodes[k].next;if(value==RJ_NONE)return RJ_NONE;k=p->nodes[value].next;}rj_ws(p);if(p->at==p->bytes||p->text[p->at++]!=':')return RJ_NONE;}
   v=rj_value(p,depth+1);if(v==RJ_NONE)return v;uint16_t first=key==RJ_NONE?v:key;if(key!=RJ_NONE)p->nodes[key].next=v;if(last==RJ_NONE)p->nodes[n].child=first;else p->nodes[last].next=first;last=v;rj_ws(p);if(p->at==p->bytes)return RJ_NONE;unsigned end=p->text[p->at++];if(end==(c=='{'?'}':']')){p->nodes[n].end=(uint32_t)p->at;return n;}if(end!=',')return RJ_NONE;}
 }
 if(c=='t'||c=='f'||c=='n'){const char*word=c=='t'?"true":c=='f'?"false":"null";for(size_t i=0;word[i];i++)if(p->at==p->bytes||p->text[p->at++]!=(unsigned)word[i])return RJ_NONE;n=rj_new(p,c=='t'?RJ_TRUE:c=='f'?RJ_FALSE:RJ_NULL,begin);if(n!=RJ_NONE)p->nodes[n].end=(uint32_t)p->at;return n;}
 if(c=='-')p->at++;if(p->at==p->bytes)return RJ_NONE;c=p->text[p->at];if(c=='0')p->at++;else{if(c<'1'||c>'9')return RJ_NONE;while(p->at<p->bytes&&p->text[p->at]>='0'&&p->text[p->at]<='9')p->at++;}
 if(p->at<p->bytes&&p->text[p->at]=='.'){p->at++;size_t k=p->at;while(p->at<p->bytes&&p->text[p->at]>='0'&&p->text[p->at]<='9')p->at++;if(k==p->at)return RJ_NONE;}
 if(p->at<p->bytes&&(p->text[p->at]=='e'||p->text[p->at]=='E')){p->at++;if(p->at<p->bytes&&(p->text[p->at]=='+'||p->text[p->at]=='-'))p->at++;size_t k=p->at;while(p->at<p->bytes&&p->text[p->at]>='0'&&p->text[p->at]<='9')p->at++;if(k==p->at)return RJ_NONE;}
 n=rj_new(p,RJ_NUMBER,begin);if(n!=RJ_NONE)p->nodes[n].end=(uint32_t)p->at;return n;
}
int rj_parse(Rj*p,const unsigned char*b,size_t n){if(!p||!b||!n||n>4096)return 0;p->text=b;p->bytes=n;p->at=0;p->count=0;uint16_t root=rj_value(p,0);rj_ws(p);return root==0&&p->nodes[0].kind==RJ_OBJECT&&p->at==n;}
uint16_t rj_get(const Rj*p,uint16_t obj,const char*key){if(!p||obj>=p->count||p->nodes[obj].kind!=RJ_OBJECT)return RJ_NONE;for(uint16_t k=p->nodes[obj].child;k!=RJ_NONE;){uint16_t v=p->nodes[k].next;if(v==RJ_NONE)return RJ_NONE;uint32_t a=p->nodes[k].start,i=0;while(key[i]&&a+i<p->nodes[k].end&&(unsigned char)key[i]==p->text[a+i])i++;if(!key[i]&&a+i==p->nodes[k].end)return v;k=p->nodes[v].next;}return RJ_NONE;}
int rj_u64(const Rj*p,uint16_t n,uint64_t*out){if(!p||!out||n>=p->count||(p->nodes[n].kind!=RJ_NUMBER&&p->nodes[n].kind!=RJ_STRING))return 0;uint64_t v=0;const RjNode*q=&p->nodes[n];if(q->start==q->end)return 0;for(uint32_t i=q->start;i<q->end;i++){unsigned c=p->text[i];if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return 0;v=v*10+c-'0';}*out=v;return 1;}
int rj_is(const Rj*p,uint16_t n,unsigned kind){return p&&n<p->count&&p->nodes[n].kind==kind;}
